<?php
namespace App\Controllers;use App\Core\Database;use App\Core\Security;
final class ReservationController{public function index():void{$db=Database::connection();$db->exec('CREATE TABLE IF NOT EXISTS reservations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,book_id INT UNSIGNED NOT NULL,requester_name VARCHAR(150) NOT NULL,requester_id VARCHAR(60) NOT NULL,contact VARCHAR(190),reserved_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,status ENUM("pending","fulfilled","cancelled") NOT NULL DEFAULT "pending",CONSTRAINT fk_reserve_book FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE CASCADE) ENGINE=InnoDB');$rows=$db->query('SELECT r.*,b.title FROM reservations r JOIN books b ON b.id=r.book_id ORDER BY r.reserved_at DESC')->fetchAll();$title='Book Reservations';require BASE_PATH.'/app/Views/reservations/index.php';}public function create():void{$db=Database::connection();$books=$db->query('SELECT id,title FROM books ORDER BY title')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'&&Security::validCsrf($_POST['_csrf']??null)){$db->prepare('INSERT INTO reservations(book_id,requester_name,requester_id,contact) VALUES(?,?,?,?)')->execute([(int)$_POST['book_id'],trim($_POST['requester_name']),trim($_POST['requester_id']),trim($_POST['contact'])]);Security::flash('success','Reservation recorded.');Security::redirect('reservations');}$title='Create Reservation';require BASE_PATH.'/app/Views/reservations/form.php';}public function status():void{if(Security::validCsrf($_POST['_csrf']??null)){Database::connection()->prepare('UPDATE reservations SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);Security::flash('success','Reservation status updated.');}Security::redirect('reservations');}public function delete():void{if(!Security::validCsrf($_POST['_csrf']??null)){Security::flash('danger','Request expired.');Security::redirect('reservations');}$s=Database::connection()->prepare('DELETE FROM reservations WHERE id=? AND status<>"fulfilled"');$s->execute([(int)$_POST['id']]);Security::flash('success',$s->rowCount()?'Reservation deleted.':'Fulfilled reservations are protected.');Security::redirect('reservations');}}
